CREATE TABLE IF NOT EXISTS incidents (id BIGINT AUTO_INCREMENT PRIMARY KEY, ward VARCHAR(100) NOT NULL, district VARCHAR(100) NOT NULL, province VARCHAR(100) NOT NULL, occurred_at TIMESTAMP NOT NULL, reporter VARCHAR(100) NOT NULL, severity VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, latitude DOUBLE NOT NULL, longitude DOUBLE NOT NULL, indicators_json JSON NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS incident_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, actor VARCHAR(100) NOT NULL, acted_at TIMESTAMP NOT NULL, action VARCHAR(50) NOT NULL, detail VARCHAR(1000));
